1	/* ===========================================================================
2	   ALMANAC NOIR — powerline statusline configurator
3	   Warm-dark operator console. Amber sole accent. Hairline rules. 2px radius.
4	   Display: Big Shoulders Display · Body: IBM Plex Sans · Mono: JetBrains Mono.
5	   CSS only — restyles app.js-emitted classes; renames nothing.
6	   =========================================================================== */
7	@import url('https://fonts.googleapis.com/css2?family=Big+Shoulders+Display:wght@500;600;700&family=IBM+Plex+Sans:wght@400;500;600&family=JetBrains+Mono:wght@400;500;700&display=swap');
8	
9	:root {
10	  --ground:#15120d;        /* warm near-black page bg */
11	  --panel:#1c1812;
12	  --panel-hi:#221d16;      /* elevated */
13	  --bone:#e8e0cf;          /* primary text — 14.2:1 on ground */
14	  --bone-soft:#cabfa2;     /* secondary — 9.1–10.2:1, AA-body everywhere */
15	  --bone-faint:#ab9f82;    /* labels / meta — 6.4–7.1:1, AA-body everywhere */
16	  --amber:#f0a830;         /* THE single signal accent — 8.2–9.2:1 */
17	  --amber-glow:#ffc14d;    /* amber, brighter — 10.3–11.5:1 */
18	  --ember:#d8542f;         /* alert / destructive ONLY — pair with a glyph, never color alone */
19	  --hair:#3a342a;          /* hairline rules */
20	  --hair-soft:#2a251e;
21	  --radius:2px;
22	  /* semantic z-index scale — sticky masthead < tooltip */
23	  --z-masthead:5;
24	  --z-tooltip:50;
25	  --disp:'Big Shoulders Display','Arial Narrow',sans-serif;
26	  --body:'IBM Plex Sans','Helvetica Neue',sans-serif;
27	  --mono:'JetBrains Mono','SFMono-Regular',ui-monospace,monospace;
28	}
29	
30	* { box-sizing: border-box; margin: 0; padding: 0; }
31	html { font-size: 16px; }
32	body {
33	  background: var(--ground);
34	  color: var(--bone);
35	  font-family: var(--body);
36	  line-height: 1.55;
37	  -webkit-font-smoothing: antialiased;
38	  font-variant-numeric: tabular-nums;
39	  /* faint engineering grid — the almanac substrate */
40	  background-image:
41	    linear-gradient(var(--hair-soft) 1px, transparent 1px),
42	    linear-gradient(90deg, var(--hair-soft) 1px, transparent 1px);
43	  background-size: 46px 46px;
44	  background-position: -1px -1px;
45	}
46	
47	/* ---------- masthead — the instrument header band ---------------------- */
48	.topbar {
49	  display: flex; align-items: center; justify-content: space-between;
50	  gap: 18px 24px; flex-wrap: wrap;
51	  padding: 16px clamp(20px, 4vw, 44px);
52	  background: linear-gradient(180deg, rgba(240,168,48,.05), transparent 80%), var(--panel);
53	  border-bottom: 1px solid var(--hair);
54	  position: sticky; top: 0; z-index: var(--z-masthead);
55	}
56	.brand {
57	  display: flex; align-items: baseline; gap: 11px;
58	  font-family: var(--disp); font-weight: 700; font-size: 27px;
59	  letter-spacing: .4px; line-height: .9; text-transform: uppercase;
60	  color: var(--bone);
61	}
62	.brand .mark {
63	  font-family: var(--mono); font-weight: 700; font-size: 15px;
64	  letter-spacing: 2.5px; color: var(--amber);
65	  padding: 3px 8px; border: 1px solid var(--hair); border-radius: var(--radius);
66	  background: var(--panel-hi); text-transform: none;
67	}
68	.brand .sig { color: var(--amber); }
69	.brand .sub {
70	  font-family: var(--mono); font-weight: 400; font-size: 11px;
71	  letter-spacing: 3px; color: var(--bone-faint); text-transform: uppercase;
72	  align-self: center;
73	}
74	
75	.actions { display: flex; align-items: center; gap: 14px; }
76	/* status — state carried by glyph + word, never color alone.
77	   app.js writes: "unsaved changes"(dirty) · "saving…" · "saved ✓ …"(saved)
78	   · "error: …"(err) · "loading…" · "loaded". Glyphs below are chosen to be
79	   distinct from each text (no doubled ✓ on saved). */
80	.status {
81	  display: inline-flex; align-items: baseline; gap: 7px;
82	  font-family: var(--mono); font-size: 12px; letter-spacing: 1px;
83	  text-transform: uppercase; color: var(--bone-faint);
84	  min-width: 210px; justify-content: flex-end; text-align: right;
85	}
86	.status::before {
87	  font-weight: 700; font-size: 12px; line-height: 1;
88	  flex: 0 0 auto; transform: translateY(.5px);
89	}
90	.status.dirty { color: var(--amber-glow); }
91	.status.dirty::before { content: "●"; }       /* pending — filled dot (text: "unsaved changes") */
92	.status.saved { color: var(--amber); }
93	.status.saved::before { content: "▸"; }       /* committed — text already carries its own ✓; lead with a distinct mark, no doubled check */
94	/* err — ember on panel is 4.40 (sub-AA at 12px); a recessed ground chip lifts
95	   the effective ratio to 4.65 (ground) ≥ AA-body. The ✕ glyph rides inside it. */
96	.status.err {
97	  color: var(--ember); font-weight: 600;
98	  background: var(--ground); border: 1px solid var(--hair);
99	  border-radius: var(--radius); padding: 3px 8px;
100	}
101	.status.err::before { content: "✕"; color: var(--ember); }  /* fault — distinct shape + the word "error:" */
102	
103	/* ---------- buttons ---------------------------------------------------- */
104	.btn {
105	  font-family: var(--mono); font-size: 12.5px; font-weight: 500;
106	  letter-spacing: 1px; text-transform: uppercase;
107	  border: 1px solid var(--hair); background: var(--panel-hi); color: var(--bone-soft);
108	  padding: 9px 16px; border-radius: var(--radius); cursor: pointer;
109	  transition: border-color .15s ease, color .15s ease, background .15s ease, transform .08s ease;
110	}
111	.btn:hover { border-color: var(--amber); color: var(--bone); }
112	.btn:active { transform: translateY(1px); }   /* tactile press */
113	.btn.primary {
114	  background: var(--amber); border-color: var(--amber-glow); color: var(--ground);
115	  font-weight: 700;
116	}
117	.btn.primary:hover { background: var(--amber-glow); color: var(--ground); }
118	.btn.ghost { background: transparent; }
119	.btn.ghost:hover { background: rgba(240,168,48,.07); }
120	.btn.mini {
121	  padding: 5px 9px; font-size: 12px; letter-spacing: .5px;
122	  min-width: 32px; min-height: 28px; text-align: center; line-height: 1;
123	}
124	.btn.danger { border-color: var(--hair); color: var(--bone-faint); }
125	.btn.danger:hover { border-color: var(--ember); color: var(--amber-glow); background: rgba(216,84,47,.14); }
126	
127	/* ---------- layout ----------------------------------------------------- */
128	.wrap { max-width: 1060px; margin: 0 auto; padding: 36px clamp(20px, 4vw, 44px) 80px; }
129	
130	/* ---------- framed terminal preview (signature element) ---------------- */
131	.termwin {
132	  background: var(--panel); border: 1px solid var(--hair); border-radius: var(--radius);
133	  overflow: hidden; margin-bottom: 44px;
134	  box-shadow: inset 0 0 0 1px rgba(240,168,48,.06), inset 0 1px 26px rgba(240,168,48,.04);
135	}
136	.termbar {
137	  display: flex; align-items: center; gap: 16px;
138	  padding: 11px 16px; background: var(--panel-hi);
139	  border-bottom: 1px solid var(--hair);
140	}
141	.dots { display: flex; gap: 7px; }
142	.dots i {
143	  width: 9px; height: 9px; border-radius: 50%;
144	  background: transparent; border: 1px solid var(--hair);
145	}
146	.dots i:nth-child(3) { background: var(--amber); border-color: var(--amber-glow); }
147	.termtitle {
148	  flex: 1; text-align: center;
149	  font-family: var(--mono); font-size: 11.5px; letter-spacing: 2px;
150	  text-transform: uppercase; color: var(--bone-faint);
151	}
152	.width { display: flex; align-items: center; gap: 11px; }
153	.width input[type=range] {
154	  width: 150px; accent-color: var(--amber); cursor: pointer;
155	  background: transparent;
156	}
157	.width input[type=range]:focus-visible {
158	  outline: 2px solid var(--amber-glow); outline-offset: 4px; border-radius: var(--radius);
159	}
160	.cols-badge {
161	  font-family: var(--mono); font-size: 11px; font-weight: 700; letter-spacing: 1px;
162	  color: var(--amber); background: var(--panel); border: 1px solid var(--hair);
163	  padding: 3px 9px; border-radius: var(--radius); white-space: nowrap;
164	  text-transform: uppercase;
165	}
166	.preview {
167	  font-family: "MesloLGS NF", "JetBrainsMono Nerd Font", "Hack Nerd Font",
168	    "Symbols Nerd Font", ui-monospace, Menlo, monospace;
169	  font-size: 17px; line-height: 1.85; white-space: pre; overflow-x: auto;
170	  padding: 20px 18px; min-height: 36px; background: var(--ground);
171	  color: var(--bone);
172	}
173	.preview-err {
174	  color: var(--ember); font-size: 12px; padding: 0 18px; white-space: pre-wrap;
175	  font-family: var(--mono); background: var(--ground);
176	}
177	.approx {
178	  font-family: var(--mono); font-size: 11px; letter-spacing: .5px;
179	  color: var(--bone-faint); padding: 10px 18px 14px; background: var(--ground);
180	  border-top: 1px solid var(--hair-soft);
181	}
182	
183	/* ---------- numbered sections — quiet, integrated header rhythm.
184	   The 01/02/03 markers are a real ordered sequence (Theme → Segments →
185	   Custom), not decorative scaffolding — they earn their place. -------- */
186	.step { margin-bottom: 46px; }
187	.step-head { display: flex; align-items: baseline; gap: 14px; margin-bottom: 18px; }
188	.step-head .num {
189	  flex: 0 0 auto;
190	  font-family: var(--mono); font-size: 14px; font-weight: 700; letter-spacing: 1px;
191	  color: var(--amber);
192	}
193	.step-head .num::before { content: "0"; }
194	.step-head > div { flex: 1; min-width: 0; }
195	.step-head h2 {
196	  font-family: var(--disp); font-weight: 600; font-size: 25px;
197	  letter-spacing: .5px; text-transform: uppercase; color: var(--bone);
198	  line-height: 1;
199	}
200	.step-head p {
201	  font-size: 13.5px; color: var(--bone-soft); margin-top: 8px; line-height: 1.55;
202	  max-width: 68ch;
203	}
204	.step-body {
205	  background: var(--panel); border: 1px solid var(--hair); border-radius: var(--radius);
206	  padding: 4px 22px;
207	}
208	
209	/* ---------- theme / display + custom rows (.field) --------------------- */
210	.field {
211	  display: flex; align-items: center; justify-content: space-between; gap: 18px;
212	  padding: 15px 0; border-bottom: 1px solid var(--hair-soft);
213	}
214	.field:last-child { border-bottom: 0; }
215	.field > label {
216	  color: var(--bone); font-size: 14.5px; font-weight: 500; line-height: 1.4;
217	  cursor: default;
218	}
219	/* .ctl = flex container so select / input / switch all right-align cleanly */
220	.field .ctl {
221	  display: flex; align-items: center; justify-content: flex-end; flex-shrink: 0;
222	}
223	.field .ctl select,
224	.field .ctl input {
225	  font-family: var(--mono); font-size: 13px;
226	  background: var(--panel-hi); color: var(--bone); border: 1px solid var(--hair);
227	  border-radius: var(--radius); padding: 8px 11px;
228	  transition: border-color .15s ease;
229	}
230	.field .ctl select:hover,
231	.field .ctl input:hover { border-color: var(--bone-faint); }
232	/* amber border on any focus; suppress the UA outline only for non-keyboard
233	   focus, so the keyboard ring below still fires (color alone never carries
234	   focus). */
235	.field .ctl select:focus,
236	.field .ctl input:focus { border-color: var(--amber); }
237	.field .ctl select:focus:not(:focus-visible),
238	.field .ctl input:focus:not(:focus-visible) { outline: none; }
239	.field .ctl select:focus-visible,
240	.field .ctl input:focus-visible {
241	  border-color: var(--amber); outline: 2px solid var(--amber-glow);
242	  outline-offset: 2px;
243	}
244	.field .ctl input[type=number] { width: 120px; }
245	
246	/* ---------- lines + segments ------------------------------------------- */
247	.lineblock {
248	  border: 1px solid var(--hair); border-radius: var(--radius);
249	  padding: 16px; margin: 16px 0; background: var(--panel-hi);
250	}
251	.lineblock > .lhead {
252	  display: flex; align-items: center; justify-content: space-between;
253	  margin-bottom: 14px; padding-bottom: 12px; border-bottom: 1px solid var(--hair-soft);
254	}
255	.lhead .ltitle {
256	  font-family: var(--mono); font-weight: 700; font-size: 12px;
257	  letter-spacing: 2px; text-transform: uppercase; color: var(--amber);
258	}
259	
260	/* segment — on/off carried by the toggle knob position (primary, non-color),
261	   opacity (secondary), and the icon: amber when on, faint when off. The amber
262	   accent stays scarce (icon + focus), not a perimeter stripe on every row. */
263	.seg {
264	  border: 1px solid var(--hair);
265	  border-radius: var(--radius); padding: 13px 15px; margin-bottom: 10px;
266	  background: var(--panel);
267	  transition: border-color .16s ease, opacity .16s ease, background .16s ease;
268	}
269	.seg:not(.off):hover { border-color: var(--bone-faint); }
270	.seg.off { opacity: .55; background: var(--ground); }
271	.seg.off .seg-icon { color: var(--bone-faint); }
272	.seg .seg-row { display: flex; align-items: center; gap: 13px; }
273	.seg .seg-icon {
274	  color: var(--amber); font-size: 16px; min-width: 18px; text-align: center;
275	  font-family: var(--mono); transition: color .16s ease;
276	}
277	.seg .seg-name {
278	  font-family: var(--disp); font-weight: 600; font-size: 18px; letter-spacing: .4px;
279	  text-transform: uppercase; color: var(--bone); cursor: help;
280	  border-bottom: 1px dotted var(--bone-soft);
281	  transition: border-color .15s ease;
282	}
283	.seg .seg-name:hover { border-bottom-color: var(--amber); }
284	.seg .grow { flex: 1; }
285	
286	.seg .opts {
287	  margin-top: 14px; padding-top: 13px; border-top: 1px solid var(--hair-soft);
288	  display: flex; flex-wrap: wrap; gap: 12px 22px;
289	}
290	/* .opt has two child orders (bool: [switch,label] · enum/num/text: [label,control]) —
291	   flex with row-align keeps both readable. */
292	.opt {
293	  display: flex; align-items: center; gap: 9px;
294	  font-family: var(--mono); font-size: 12.5px; color: var(--bone-soft);
295	  letter-spacing: .3px;
296	}
297	.opt select,
298	.opt input[type=text],
299	.opt input[type=number] {
300	  font-family: var(--mono); font-size: 12.5px;
301	  background: var(--panel-hi); color: var(--bone); border: 1px solid var(--hair);
302	  border-radius: var(--radius); padding: 6px 9px;
303	  transition: border-color .15s ease;
304	}
305	.opt select:hover,
306	.opt input:hover { border-color: var(--bone-faint); }
307	.opt select:focus,
308	.opt input:focus { border-color: var(--amber); }
309	.opt select:focus:not(:focus-visible),
310	.opt input:focus:not(:focus-visible) { outline: none; }
311	.opt select:focus-visible,
312	.opt input:focus-visible {
313	  border-color: var(--amber); outline: 2px solid var(--amber-glow); outline-offset: 2px;
314	}
315	.opt input[type=text] { width: 150px; }
316	.opt input[type=number] { width: 100px; }
317	
318	/* folded budget / context-limits sub-block inside a segment */
319	.fold {
320	  margin-top: 14px; border: 1px dashed var(--hair); border-radius: var(--radius);
321	  padding: 12px 14px; background: var(--ground);
322	}
323	.fold .fold-title {
324	  font-family: var(--mono); font-size: 11px; font-weight: 700;
325	  letter-spacing: 1.5px; text-transform: uppercase; color: var(--amber);
326	  margin-bottom: 10px;
327	}
328	.fold .opts { margin-top: 0; padding-top: 0; border-top: 0; }
329	
330	.addrow { display: flex; gap: 10px; margin: 14px 0 4px; }
331	.addrow select {
332	  flex: 1; font-family: var(--mono); font-size: 13px;
333	  background: var(--panel); color: var(--bone-soft); border: 1px dashed var(--hair);
334	  border-radius: var(--radius); padding: 10px 11px; cursor: pointer;
335	  transition: border-color .15s ease, color .15s ease;
336	}
337	.addrow select:hover { border-color: var(--amber); color: var(--bone); }
338	.addrow select:focus { border-color: var(--amber); }
339	.addrow select:focus:not(:focus-visible) { outline: none; }
340	.addrow select:focus-visible {
341	  border-color: var(--amber); outline: 2px solid var(--amber-glow); outline-offset: 2px;
342	}
343	
344	/* ---------- the toggle switch — works in EVERY parent (bug #1 fix) ------ */
345	/* inline-block so width/height apply outside flex parents (theme/custom rows) */
346	.switch {
347	  display: inline-block; position: relative;
348	  width: 42px; height: 22px; flex: 0 0 auto; vertical-align: middle; cursor: pointer;
349	}
350	.switch input { position: absolute; opacity: 0; width: 0; height: 0; }
351	/* OFF: visibly a track (recessed panel-hi well + hairline) with the knob parked
352	   left. ON: amber track, knob parked right. Knob POSITION is the non-color cue. */
353	.switch .slider {
354	  position: absolute; inset: 0;
355	  background: var(--panel-hi); border: 1px solid var(--hair);
356	  border-radius: 22px; transition: background .15s ease, border-color .15s ease;
357	  cursor: pointer;
358	}
359	.switch:hover .slider { border-color: var(--bone-faint); }
360	.switch .slider::before {
361	  content: ""; position: absolute;
362	  width: 16px; height: 16px; left: 2px; top: 2px;
363	  background: var(--bone-faint); border-radius: 50%;
364	  transition: transform .15s ease, background .15s ease;
365	}
366	.switch input:checked + .slider {
367	  background: var(--amber); border-color: var(--amber-glow);
368	}
369	.switch:hover input:checked + .slider { border-color: var(--amber-glow); }
370	.switch input:checked + .slider::before {
371	  transform: translateX(20px); background: var(--ground);
372	}
373	.switch input:focus-visible + .slider { outline: 2px solid var(--amber-glow); outline-offset: 3px; }
374	
375	/* ---------- tooltip ---------------------------------------------------- */
376	.tooltip {
377	  position: fixed; max-width: 300px;
378	  background: var(--panel-hi); color: var(--bone-soft);
379	  border: 1px solid var(--hair);
380	  border-radius: var(--radius); padding: 11px 14px;
381	  font-size: 13px; line-height: 1.55; z-index: var(--z-tooltip); pointer-events: none;
382	  /* a floating popover earns a lift; tightened blur + amber inset edge keeps it
383	     in the inset-glow family rather than a soft generic drop shadow. */
384	  box-shadow: inset 0 0 0 1px rgba(240,168,48,.10), 0 6px 18px rgba(0,0,0,.45);
385	}
386	.tooltip .tt-title {
387	  font-family: var(--disp); font-weight: 700; font-size: 15px; letter-spacing: .4px;
388	  text-transform: uppercase; color: var(--amber); margin-bottom: 5px;
389	}
390	
391	/* ---------- accessibility floor ----------------------------------------
392	   Base keyboard ring for every interactive element. High-traffic controls
393	   (selects/inputs/toggle/slider) layer amber-glow rings above this. */
394	:focus-visible { outline: 2px solid var(--amber); outline-offset: 2px; border-radius: var(--radius); }
395	/* Kill ALL motion — transitions AND any animation — when the user asks. */
396	@media (prefers-reduced-motion: reduce) {
397	  *, *::before, *::after {
398	    transition: none !important;
399	    animation: none !important;
400	    scroll-behavior: auto !important;
401	  }
402	}
403	
404	/* ---------- responsive ------------------------------------------------- */
405	@media (max-width: 640px) {
406	  .topbar { flex-direction: column; align-items: flex-start; }
407	  .actions { width: 100%; justify-content: flex-end; }
408	  .status { min-width: 0; flex: 1; justify-content: flex-start; text-align: left; }
409	  .field { flex-direction: column; align-items: stretch; gap: 8px; }
410	  .field .ctl { justify-content: flex-start; }
411	  .seg .opts { gap: 12px 18px; }
412	  .width input[type=range] { width: 110px; }
413	}
414

