/* ===========================================================================
   ALMANAC NOIR — powerline statusline configurator
   Warm-dark operator console. Amber sole accent. Hairline rules. 2px radius.
   Display: Big Shoulders Display · Body: IBM Plex Sans · Mono: JetBrains Mono.
   CSS only — restyles app.js-emitted classes; renames nothing.
   =========================================================================== */
@import url('https://fonts.googleapis.com/css2?family=Big+Shoulders+Display:wght@500;600;700&family=IBM+Plex+Sans:wght@400;500;600&family=JetBrains+Mono:wght@400;500;700&display=swap');

:root {
  --ground:#15120d;        /* warm near-black page bg */
  --panel:#1c1812;
  --panel-hi:#221d16;      /* elevated */
  --bone:#e8e0cf;          /* primary text — 14.2:1 on ground */
  --bone-soft:#cabfa2;     /* secondary — 9.1–10.2:1, AA-body everywhere */
  --bone-faint:#ab9f82;    /* labels / meta — 6.4–7.1:1, AA-body everywhere */
  --amber:#f0a830;         /* THE single signal accent — 8.2–9.2:1 */
  --amber-glow:#ffc14d;    /* amber, brighter — 10.3–11.5:1 */
  --ember:#d8542f;         /* alert / destructive ONLY — pair with a glyph, never color alone */
  --hair:#3a342a;          /* hairline rules */
  --hair-soft:#2a251e;
  --radius:2px;
  /* semantic z-index scale — sticky masthead < tooltip */
  --z-masthead:5;
  --z-tooltip:50;
  --disp:'Big Shoulders Display','Arial Narrow',sans-serif;
  --body:'IBM Plex Sans','Helvetica Neue',sans-serif;
  --mono:'JetBrains Mono','SFMono-Regular',ui-monospace,monospace;
}

* { box-sizing: border-box; margin: 0; padding: 0; }
html { font-size: 16px; }
body {
  background: var(--ground);
  color: var(--bone);
  font-family: var(--body);
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
  font-variant-numeric: tabular-nums;
  /* faint engineering grid — the almanac substrate */
  background-image:
    linear-gradient(var(--hair-soft) 1px, transparent 1px),
    linear-gradient(90deg, var(--hair-soft) 1px, transparent 1px);
  background-size: 46px 46px;
  background-position: -1px -1px;
}

/* ---------- masthead — the instrument header band ---------------------- */
.topbar {
  display: flex; align-items: center; justify-content: space-between;
  gap: 18px 24px; flex-wrap: wrap;
  padding: 16px clamp(20px, 4vw, 44px);
  background: linear-gradient(180deg, rgba(240,168,48,.05), transparent 80%), var(--panel);
  border-bottom: 1px solid var(--hair);
  position: sticky; top: 0; z-index: var(--z-masthead);
}
.brand {
  display: flex; align-items: baseline; gap: 11px;
  font-family: var(--disp); font-weight: 700; font-size: 27px;
  letter-spacing: .4px; line-height: .9; text-transform: uppercase;
  color: var(--bone);
}
.brand .mark {
  font-family: var(--mono); font-weight: 700; font-size: 15px;
  letter-spacing: 2.5px; color: var(--amber);
  padding: 3px 8px; border: 1px solid var(--hair); border-radius: var(--radius);
  background: var(--panel-hi); text-transform: none;
}
.brand .sig { color: var(--amber); }
.brand .sub {
  font-family: var(--mono); font-weight: 400; font-size: 11px;
  letter-spacing: 3px; color: var(--bone-faint); text-transform: uppercase;
  align-self: center;
}

.actions { display: flex; align-items: center; gap: 14px; }
/* status — state carried by glyph + word, never color alone.
   app.js writes: "unsaved changes"(dirty) · "saving…" · "saved ✓ …"(saved)
   · "error: …"(err) · "loading…" · "loaded". Glyphs below are chosen to be
   distinct from each text (no doubled ✓ on saved). */
.status {
  display: inline-flex; align-items: baseline; gap: 7px;
  font-family: var(--mono); font-size: 12px; letter-spacing: 1px;
  text-transform: uppercase; color: var(--bone-faint);
  min-width: 210px; justify-content: flex-end; text-align: right;
}
.status::before {
  font-weight: 700; font-size: 12px; line-height: 1;
  flex: 0 0 auto; transform: translateY(.5px);
}
.status.dirty { color: var(--amber-glow); }
.status.dirty::before { content: "●"; }       /* pending — filled dot (text: "unsaved changes") */
.status.saved { color: var(--amber); }
.status.saved::before { content: "▸"; }       /* committed — text already carries its own ✓; lead with a distinct mark, no doubled check */
/* err — ember on panel is 4.40 (sub-AA at 12px); a recessed ground chip lifts
   the effective ratio to 4.65 (ground) ≥ AA-body. The ✕ glyph rides inside it. */
.status.err {
  color: var(--ember); font-weight: 600;
  background: var(--ground); border: 1px solid var(--hair);
  border-radius: var(--radius); padding: 3px 8px;
}
.status.err::before { content: "✕"; color: var(--ember); }  /* fault — distinct shape + the word "error:" */

/* ---------- buttons ---------------------------------------------------- */
.btn {
  font-family: var(--mono); font-size: 12.5px; font-weight: 500;
  letter-spacing: 1px; text-transform: uppercase;
  border: 1px solid var(--hair); background: var(--panel-hi); color: var(--bone-soft);
  padding: 9px 16px; border-radius: var(--radius); cursor: pointer;
  transition: border-color .15s ease, color .15s ease, background .15s ease, transform .08s ease;
}
.btn:hover { border-color: var(--amber); color: var(--bone); }
.btn:active { transform: translateY(1px); }   /* tactile press */
.btn.primary {
  background: var(--amber); border-color: var(--amber-glow); color: var(--ground);
  font-weight: 700;
}
.btn.primary:hover { background: var(--amber-glow); color: var(--ground); }
.btn.ghost { background: transparent; }
.btn.ghost:hover { background: rgba(240,168,48,.07); }
.btn.mini {
  padding: 5px 9px; font-size: 12px; letter-spacing: .5px;
  min-width: 32px; min-height: 28px; text-align: center; line-height: 1;
}
.btn.danger { border-color: var(--hair); color: var(--bone-faint); }
.btn.danger:hover { border-color: var(--ember); color: var(--amber-glow); background: rgba(216,84,47,.14); }

/* ---------- layout ----------------------------------------------------- */
.wrap { max-width: 1060px; margin: 0 auto; padding: 36px clamp(20px, 4vw, 44px) 80px; }

/* ---------- framed terminal preview (signature element) ---------------- */
.termwin {
  background: var(--panel); border: 1px solid var(--hair); border-radius: var(--radius);
  overflow: hidden; margin-bottom: 44px;
  box-shadow: inset 0 0 0 1px rgba(240,168,48,.06), inset 0 1px 26px rgba(240,168,48,.04);
}
.termbar {
  display: flex; align-items: center; gap: 16px;
  padding: 11px 16px; background: var(--panel-hi);
  border-bottom: 1px solid var(--hair);
}
.dots { display: flex; gap: 7px; }
.dots i {
  width: 9px; height: 9px; border-radius: 50%;
  background: transparent; border: 1px solid var(--hair);
}
.dots i:nth-child(3) { background: var(--amber); border-color: var(--amber-glow); }
.termtitle {
  flex: 1; text-align: center;
  font-family: var(--mono); font-size: 11.5px; letter-spacing: 2px;
  text-transform: uppercase; color: var(--bone-faint);
}
.width { display: flex; align-items: center; gap: 11px; }
.width input[type=range] {
  width: 150px; accent-color: var(--amber); cursor: pointer;
  background: transparent;
}
.width input[type=range]:focus-visible {
  outline: 2px solid var(--amber-glow); outline-offset: 4px; border-radius: var(--radius);
}
.cols-badge {
  font-family: var(--mono); font-size: 11px; font-weight: 700; letter-spacing: 1px;
  color: var(--amber); background: var(--panel); border: 1px solid var(--hair);
  padding: 3px 9px; border-radius: var(--radius); white-space: nowrap;
  text-transform: uppercase;
}
.preview {
  font-family: "MesloLGS NF", "JetBrainsMono Nerd Font", "Hack Nerd Font",
    "Symbols Nerd Font", ui-monospace, Menlo, monospace;
  font-size: 17px; line-height: 1.85; white-space: pre; overflow-x: auto;
  padding: 20px 18px; min-height: 36px; background: var(--ground);
  color: var(--bone);
}
.preview-err {
  color: var(--ember); font-size: 12px; padding: 0 18px; white-space: pre-wrap;
  font-family: var(--mono); background: var(--ground);
}
.approx {
  font-family: var(--mono); font-size: 11px; letter-spacing: .5px;
  color: var(--bone-faint); padding: 10px 18px 14px; background: var(--ground);
  border-top: 1px solid var(--hair-soft);
}

/* ---------- numbered sections — quiet, integrated header rhythm.
   The 01/02/03 markers are a real ordered sequence (Theme → Segments →
   Custom), not decorative scaffolding — they earn their place. -------- */
.step { margin-bottom: 46px; }
.step-head { display: flex; align-items: baseline; gap: 14px; margin-bottom: 18px; }
.step-head .num {
  flex: 0 0 auto;
  font-family: var(--mono); font-size: 14px; font-weight: 700; letter-spacing: 1px;
  color: var(--amber);
}
.step-head .num::before { content: "0"; }
.step-head > div { flex: 1; min-width: 0; }
.step-head h2 {
  font-family: var(--disp); font-weight: 600; font-size: 25px;
  letter-spacing: .5px; text-transform: uppercase; color: var(--bone);
  line-height: 1;
}
.step-head p {
  font-size: 13.5px; color: var(--bone-soft); margin-top: 8px; line-height: 1.55;
  max-width: 68ch;
}
.step-body {
  background: var(--panel); border: 1px solid var(--hair); border-radius: var(--radius);
  padding: 4px 22px;
}

/* ---------- theme / display + custom rows (.field) --------------------- */
.field {
  display: flex; align-items: center; justify-content: space-between; gap: 18px;
  padding: 15px 0; border-bottom: 1px solid var(--hair-soft);
}
.field:last-child { border-bottom: 0; }
.field > label {
  color: var(--bone); font-size: 14.5px; font-weight: 500; line-height: 1.4;
  cursor: default;
}
/* .ctl = flex container so select / input / switch all right-align cleanly */
.field .ctl {
  display: flex; align-items: center; justify-content: flex-end; flex-shrink: 0;
}
.field .ctl select,
.field .ctl input {
  font-family: var(--mono); font-size: 13px;
  background: var(--panel-hi); color: var(--bone); border: 1px solid var(--hair);
  border-radius: var(--radius); padding: 8px 11px;
  transition: border-color .15s ease;
}
.field .ctl select:hover,
.field .ctl input:hover { border-color: var(--bone-faint); }
/* amber border on any focus; suppress the UA outline only for non-keyboard
   focus, so the keyboard ring below still fires (color alone never carries
   focus). */
.field .ctl select:focus,
.field .ctl input:focus { border-color: var(--amber); }
.field .ctl select:focus:not(:focus-visible),
.field .ctl input:focus:not(:focus-visible) { outline: none; }
.field .ctl select:focus-visible,
.field .ctl input:focus-visible {
  border-color: var(--amber); outline: 2px solid var(--amber-glow);
  outline-offset: 2px;
}
.field .ctl input[type=number] { width: 120px; }

/* ---------- lines + segments ------------------------------------------- */
.lineblock {
  border: 1px solid var(--hair); border-radius: var(--radius);
  padding: 16px; margin: 16px 0; background: var(--panel-hi);
}
.lineblock > .lhead {
  display: flex; align-items: center; justify-content: space-between;
  margin-bottom: 14px; padding-bottom: 12px; border-bottom: 1px solid var(--hair-soft);
}
.lhead .ltitle {
  font-family: var(--mono); font-weight: 700; font-size: 12px;
  letter-spacing: 2px; text-transform: uppercase; color: var(--amber);
}

/* segment — on/off carried by the toggle knob position (primary, non-color),
   opacity (secondary), and the icon: amber when on, faint when off. The amber
   accent stays scarce (icon + focus), not a perimeter stripe on every row. */
.seg {
  border: 1px solid var(--hair);
  border-radius: var(--radius); padding: 13px 15px; margin-bottom: 10px;
  background: var(--panel);
  transition: border-color .16s ease, opacity .16s ease, background .16s ease;
}
.seg:not(.off):hover { border-color: var(--bone-faint); }
.seg.off { opacity: .55; background: var(--ground); }
.seg.off .seg-icon { color: var(--bone-faint); }
.seg .seg-row { display: flex; align-items: center; gap: 13px; }
.seg .seg-icon {
  color: var(--amber); font-size: 16px; min-width: 18px; text-align: center;
  font-family: var(--mono); transition: color .16s ease;
}
.seg .seg-name {
  font-family: var(--disp); font-weight: 600; font-size: 18px; letter-spacing: .4px;
  text-transform: uppercase; color: var(--bone); cursor: help;
  border-bottom: 1px dotted var(--bone-soft);
  transition: border-color .15s ease;
}
.seg .seg-name:hover { border-bottom-color: var(--amber); }
.seg .grow { flex: 1; }

.seg .opts {
  margin-top: 14px; padding-top: 13px; border-top: 1px solid var(--hair-soft);
  display: flex; flex-wrap: wrap; gap: 12px 22px;
}
/* .opt has two child orders (bool: [switch,label] · enum/num/text: [label,control]) —
   flex with row-align keeps both readable. */
.opt {
  display: flex; align-items: center; gap: 9px;
  font-family: var(--mono); font-size: 12.5px; color: var(--bone-soft);
  letter-spacing: .3px;
}
.opt select,
.opt input[type=text],
.opt input[type=number] {
  font-family: var(--mono); font-size: 12.5px;
  background: var(--panel-hi); color: var(--bone); border: 1px solid var(--hair);
  border-radius: var(--radius); padding: 6px 9px;
  transition: border-color .15s ease;
}
.opt select:hover,
.opt input:hover { border-color: var(--bone-faint); }
.opt select:focus,
.opt input:focus { border-color: var(--amber); }
.opt select:focus:not(:focus-visible),
.opt input:focus:not(:focus-visible) { outline: none; }
.opt select:focus-visible,
.opt input:focus-visible {
  border-color: var(--amber); outline: 2px solid var(--amber-glow); outline-offset: 2px;
}
.opt input[type=text] { width: 150px; }
.opt input[type=number] { width: 100px; }

/* folded budget / context-limits sub-block inside a segment */
.fold {
  margin-top: 14px; border: 1px dashed var(--hair); border-radius: var(--radius);
  padding: 12px 14px; background: var(--ground);
}
.fold .fold-title {
  font-family: var(--mono); font-size: 11px; font-weight: 700;
  letter-spacing: 1.5px; text-transform: uppercase; color: var(--amber);
  margin-bottom: 10px;
}
.fold .opts { margin-top: 0; padding-top: 0; border-top: 0; }

.addrow { display: flex; gap: 10px; margin: 14px 0 4px; }
.addrow select {
  flex: 1; font-family: var(--mono); font-size: 13px;
  background: var(--panel); color: var(--bone-soft); border: 1px dashed var(--hair);
  border-radius: var(--radius); padding: 10px 11px; cursor: pointer;
  transition: border-color .15s ease, color .15s ease;
}
.addrow select:hover { border-color: var(--amber); color: var(--bone); }
.addrow select:focus { border-color: var(--amber); }
.addrow select:focus:not(:focus-visible) { outline: none; }
.addrow select:focus-visible {
  border-color: var(--amber); outline: 2px solid var(--amber-glow); outline-offset: 2px;
}

/* ---------- the toggle switch — works in EVERY parent (bug #1 fix) ------ */
/* inline-block so width/height apply outside flex parents (theme/custom rows) */
.switch {
  display: inline-block; position: relative;
  width: 42px; height: 22px; flex: 0 0 auto; vertical-align: middle; cursor: pointer;
}
.switch input { position: absolute; opacity: 0; width: 0; height: 0; }
/* OFF: visibly a track (recessed panel-hi well + hairline) with the knob parked
   left. ON: amber track, knob parked right. Knob POSITION is the non-color cue. */
.switch .slider {
  position: absolute; inset: 0;
  background: var(--panel-hi); border: 1px solid var(--hair);
  border-radius: 22px; transition: background .15s ease, border-color .15s ease;
  cursor: pointer;
}
.switch:hover .slider { border-color: var(--bone-faint); }
.switch .slider::before {
  content: ""; position: absolute;
  width: 16px; height: 16px; left: 2px; top: 2px;
  background: var(--bone-faint); border-radius: 50%;
  transition: transform .15s ease, background .15s ease;
}
.switch input:checked + .slider {
  background: var(--amber); border-color: var(--amber-glow);
}
.switch:hover input:checked + .slider { border-color: var(--amber-glow); }
.switch input:checked + .slider::before {
  transform: translateX(20px); background: var(--ground);
}
.switch input:focus-visible + .slider { outline: 2px solid var(--amber-glow); outline-offset: 3px; }

/* ---------- tooltip ---------------------------------------------------- */
.tooltip {
  position: fixed; max-width: 300px;
  background: var(--panel-hi); color: var(--bone-soft);
  border: 1px solid var(--hair);
  border-radius: var(--radius); padding: 11px 14px;
  font-size: 13px; line-height: 1.55; z-index: var(--z-tooltip); pointer-events: none;
  /* a floating popover earns a lift; tightened blur + amber inset edge keeps it
     in the inset-glow family rather than a soft generic drop shadow. */
  box-shadow: inset 0 0 0 1px rgba(240,168,48,.10), 0 6px 18px rgba(0,0,0,.45);
}
.tooltip .tt-title {
  font-family: var(--disp); font-weight: 700; font-size: 15px; letter-spacing: .4px;
  text-transform: uppercase; color: var(--amber); margin-bottom: 5px;
}

/* ---------- accessibility floor ----------------------------------------
   Base keyboard ring for every interactive element. High-traffic controls
   (selects/inputs/toggle/slider) layer amber-glow rings above this. */
:focus-visible { outline: 2px solid var(--amber); outline-offset: 2px; border-radius: var(--radius); }
/* Kill ALL motion — transitions AND any animation — when the user asks. */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    transition: none !important;
    animation: none !important;
    scroll-behavior: auto !important;
  }
}

/* ---------- responsive ------------------------------------------------- */
@media (max-width: 640px) {
  .topbar { flex-direction: column; align-items: flex-start; }
  .actions { width: 100%; justify-content: flex-end; }
  .status { min-width: 0; flex: 1; justify-content: flex-start; text-align: left; }
  .field { flex-direction: column; align-items: stretch; gap: 8px; }
  .field .ctl { justify-content: flex-start; }
  .seg .opts { gap: 12px 18px; }
  .width input[type=range] { width: 110px; }
}
